package techguns.client.render.block.pipe;

import java.util.HashMap;
import java.util.Map;

import net.minecraft.client.renderer.block.BlockModelShaper;
import net.minecraft.client.resources.model.BakedModel;
import net.minecraft.client.resources.model.ModelResourceLocation;
import net.neoforged.neoforge.client.event.ModelEvent;
import techguns.TGIds;
import techguns.registry.TGBlocks;
import techguns.transport.PipeParts;

/**
 * Loads the pipe part models ({@code block/pipe/part/*}, generated by {@code TGPipeModelProvider}) as standalone models
 * and puts the {@link PipeBakedModel} in place of the pipe block's model.
 */
// MIGRATION(26.x): standalone models and ModifyBakingResult change with the model system rework in 1.21.4+.
public final class PipeModels {
    private PipeModels() {
    }

    private static ModelResourceLocation part(String name) {
        return ModelResourceLocation.standalone(TGIds.id("block/pipe/part/" + name));
    }

    public static void registerAdditional(ModelEvent.RegisterAdditional event) {
        PipeParts.allModels().forEach(name -> event.register(part(name)));
    }

    public static void modifyBakingResult(ModelEvent.ModifyBakingResult event) {
        Map<ModelResourceLocation, BakedModel> models = event.getModels();
        Map<String, BakedModel> parts = new HashMap<>();
        for (String name : PipeParts.allModels()) {
            BakedModel model = models.get(part(name));
            if (model != null) {
                parts.put(name, model);
            }
        }
        TGBlocks.PIPE.get().getStateDefinition().getPossibleStates().forEach(state -> {
            ModelResourceLocation location = BlockModelShaper.stateToModelLocation(state);
            BakedModel base = models.get(location);
            if (base != null) {
                models.put(location, new PipeBakedModel(parts, base));
            }
        });
    }
}
